use super::*;
use crate::mail::conversation::{
    graph::{Boundary, Folder, Work},
    identity::{ContentFingerprint, ThreadFacts},
    state::Options,
    store::{Binding, CursorStore},
};
use std::time::Instant;

const ACCOUNT: [u8; 32] = [3; 32];
const HEADER: &[u8] = b"Message-ID: <seed@local>\r\nReferences: <parent@local>\r\n\r\n";

#[test]
fn the_r11a_live_wire_fixture_keeps_its_committed_delivery_and_legacy_charge() {
    // Generated by persist::encode from the exact d2673f7 source. Its AMD64
    // State was 440 bytes and its fully populated owned charge was 817 bytes.
    let wire = include_bytes!("fixtures/live-v1.bin");
    let (state, replay) = decode(&mut wire.as_slice(), wire.len(), 817, [1; 32]).unwrap();
    assert!(std::mem::size_of::<State>() <= 440);
    assert!(state.cache_stamps().is_none());
    assert!(state.owned_bytes() <= 817);
    assert_eq!(state.seed().uid, 1);
    assert!(state.plan_delta().items().is_empty());
    let replay = replay.unwrap();
    assert!(!replay.input.cached());
    assert!(!replay.next.unwrap().cached());
    assert_eq!(replay.delivery.items().len(), 1);
    assert!(replay.wire_omitted);
}

#[test]
fn cached_cursor_routes_without_changing_the_uuid_shape_and_rejects_a_source_switch() {
    let now = Instant::now();
    let store = CursorStore::default();
    let lease = store
        .open_lease(Binding::new(ACCOUNT, "subject"), now, |limit| {
            let mut state = state(limit)?;
            let mut stamps = [None; super::super::MAX_FOLDERS];
            stamps[0] = Some(CacheStamp {
                checked_at_ms: 123,
                index_revision: 5,
                dirty_revision: 2,
                restore_epoch: 1,
                complete_headers: 3,
                indexed_threads: 2,
                known_messages: 4,
            });
            state.set_cache_stamps(stamps, limit)?;
            Ok(state)
        })
        .unwrap();
    let prepared = lease.prepare(lease.state().plan_delta()).unwrap();
    let cursor = prepared.next().unwrap().to_string();
    let route = super::super::super::cached_request;
    assert_eq!(cursor.len(), 36);
    assert!(route(&serde_json::json!({"cursor":cursor})).unwrap());
    assert!(route(&serde_json::json!({"cursor":cursor,"read_source":"cache"})).unwrap());
    assert!(route(&serde_json::json!({"cursor":cursor,"read_source":"live"})).is_err());
    let mut wire = Vec::new();
    encode(&mut wire, lease.state(), &prepared, true).unwrap();
    let (restored, replay) = decode(
        &mut wire.as_slice(),
        wire.len(),
        lease.state().owned_bytes(),
        ACCOUNT,
    )
    .unwrap();
    assert_eq!(
        restored.cache_stamps().unwrap()[0].unwrap().index_revision,
        5
    );
    assert!(replay.unwrap().input.cached());
}

fn facts() -> ThreadFacts {
    ThreadFacts::parse(&mailparse::parse_headers(HEADER).unwrap().0).unwrap()
}

fn state(limit: usize) -> std::result::Result<State, super::super::StateError> {
    let mut state = State::new(
        ACCOUNT,
        vec![
            Folder {
                name: "INBOX".into(),
                boundary: Boundary::Frozen {
                    uid_validity: 7,
                    high_uid: 501,
                },
            },
            Folder {
                name: "归档".into(),
                boundary: Boundary::Unavailable(Failure::Backend),
            },
        ],
        RefKey { folder: 0, uid: 1 },
        Options::default(),
        facts(),
        limit,
    )?;
    state.reserve_restore_scratch();
    Ok(state)
}

#[test]
fn projected_emitted_graph_and_latest_page_restore_without_mutating_the_lease() {
    let now = Instant::now();
    let store = CursorStore::default();
    let mut lease = store
        .open_lease(Binding::new(ACCOUNT, "subject"), now, state)
        .unwrap();
    let Work::Search(search) = lease.state().next_work().unwrap() else {
        panic!("expected search");
    };
    lease
        .update(|state, limit| state.apply_search(search, &[500], limit))
        .unwrap();
    let Work::Verify(candidate) = lease.state().next_work().unwrap() else {
        panic!("expected candidate");
    };
    lease
        .update(|state, limit| state.apply_facts(candidate, facts(), limit))
        .unwrap();
    let mut delivery = lease.state().plan_delta();
    assert_eq!(delivery.items().len(), 2);
    delivery.truncate(1);
    let prepared = lease
        .prepare_with_outcome(delivery.clone(), true, true)
        .unwrap();
    let mut data = Vec::new();
    assert_eq!(
        encode(&mut data, lease.state(), &prepared, true).unwrap(),
        data.len()
    );
    let (restored, replay) = decode(
        &mut data.as_slice(),
        data.len(),
        lease.state().owned_bytes(),
        ACCOUNT,
    )
    .unwrap();
    assert_eq!(lease.state().plan_delta().items().len(), 2);
    assert_eq!(restored.plan_delta().items().len(), 1);
    let replay = replay.unwrap();
    assert!(replay.next == prepared.next());
    assert!(replay.capacity_reached && replay.wire_omitted);
    assert_eq!(replay.delivery.items(), delivery.items());
    assert_eq!(replay.coverage, prepared.coverage());
}

fn fixture() -> Vec<u8> {
    let now = Instant::now();
    let store = CursorStore::default();
    let lease = store
        .open_lease(Binding::new(ACCOUNT, "subject"), now, state)
        .unwrap();
    let prepared = lease.prepare(lease.state().plan_delta()).unwrap();
    let mut data = Vec::new();
    encode(&mut data, lease.state(), &prepared, false).unwrap();
    data
}

fn resign(data: &mut [u8]) {
    let (payload, checksum) = data.split_at_mut(data.len() - CHECKSUM_BYTES);
    checksum.copy_from_slice(&Sha256::digest(payload));
}

#[test]
fn invalid_lengths_versions_tail_and_budget_fail_before_restoration() {
    let data = fixture();
    for len in 0..data.len() {
        assert!(decode(&mut &data[..len], len, MAX_ENCODED, ACCOUNT).is_err());
    }
    assert!(decode(&mut data.as_slice(), data.len(), 1, ACCOUNT).is_err());
    assert!(decode(&mut data.as_slice(), data.len(), MAX_ENCODED, [9; 32]).is_err());
    assert!(decode(&mut data.as_slice(), MAX_ENCODED + 1, MAX_ENCODED, ACCOUNT).is_err());

    let mut invalid = data.clone();
    invalid[8] = 9;
    resign(&mut invalid);
    assert!(decode(&mut invalid.as_slice(), invalid.len(), MAX_ENCODED, ACCOUNT).is_err());

    let mut invalid = data.clone();
    invalid[44] = 255;
    resign(&mut invalid);
    assert!(decode(&mut invalid.as_slice(), invalid.len(), MAX_ENCODED, ACCOUNT).is_err());

    let mut invalid = data.clone();
    invalid[45..47].copy_from_slice(&u16::MAX.to_be_bytes());
    resign(&mut invalid);
    assert!(decode(&mut invalid.as_slice(), invalid.len(), MAX_ENCODED, ACCOUNT).is_err());

    let mut invalid = data.clone();
    invalid[47] ^= 0x20;
    assert!(decode(&mut invalid.as_slice(), invalid.len(), MAX_ENCODED, ACCOUNT).is_err());

    let mut invalid = data.clone();
    invalid.push(0);
    assert!(decode(&mut invalid.as_slice(), data.len(), MAX_ENCODED, ACCOUNT).is_err());
}

#[test]
fn checksummed_counts_watermarks_and_graph_indices_still_require_valid_records() {
    let data = fixture();
    // Skip the fixed prefix and the two fixture folder records. The option
    // byte is zero and carries no body limit value in this fixture.
    let targets = 45 + 17 + 9 + 5 + 4 + 4 + 1 + 2 + 4 + 1 + 8;
    assert_eq!(&data[targets..targets + 4], &2u32.to_be_bytes());
    let first_window = targets + 4 + 2 + b"<seed@local>".len();
    assert_eq!(&data[first_window..first_window + 4], &501u32.to_be_bytes());
    let seed_location = data.len() - CHECKSUM_BYTES - 1 - 10;
    let variant_index = seed_location + 5;
    for (start, bytes) in [
        (targets, u32::MAX.to_be_bytes()),
        (first_window, 500u32.to_be_bytes()),
        (variant_index, 5u32.to_be_bytes()),
    ] {
        let mut invalid = data.clone();
        invalid[start..start + bytes.len()].copy_from_slice(&bytes);
        resign(&mut invalid);
        assert!(decode(&mut invalid.as_slice(), invalid.len(), MAX_ENCODED, ACCOUNT).is_err());
    }
    let mut invalid = data.clone();
    invalid[seed_location] = 1;
    resign(&mut invalid);
    assert!(decode(&mut invalid.as_slice(), invalid.len(), MAX_ENCODED, ACCOUNT).is_err());

    let mut invalid = data.clone();
    let parent = b"<parent@local>";
    let duplicate = b"<seed@local>";
    let start = data
        .windows(parent.len())
        .position(|part| part == parent)
        .unwrap();
    let replacement = (duplicate.len() as u16)
        .to_be_bytes()
        .into_iter()
        .chain(duplicate.iter().copied());
    invalid.splice(start - 2..start + parent.len(), replacement);
    resign(&mut invalid);
    assert!(decode(&mut invalid.as_slice(), invalid.len(), MAX_ENCODED, ACCOUNT).is_err());
}

#[test]
fn checksummed_duplicate_locations_and_candidate_predicates_are_rejected() {
    let now = Instant::now();
    let store = CursorStore::default();
    let binding = Binding::new(ACCOUNT, "subject");
    let verified = || {
        let mut facts = facts();
        facts.evidence.content = Some(ContentFingerprint::raw_mime_body(b"copy"));
        facts
    };
    let mut lease = store
        .open_lease(binding, now, |limit| {
            let mut state = State::new(
                ACCOUNT,
                vec![Folder {
                    name: "INBOX".into(),
                    boundary: Boundary::Frozen {
                        uid_validity: 7,
                        high_uid: 501,
                    },
                }],
                RefKey { folder: 0, uid: 1 },
                Options::default(),
                verified(),
                limit,
            )?;
            state.reserve_restore_scratch();
            Ok(state)
        })
        .unwrap();
    let Work::Search(unit) = lease.state().next_work().unwrap() else {
        panic!("expected search");
    };
    lease
        .update(|state, limit| state.apply_search(unit, &[500, 499], limit))
        .unwrap();
    let prepared = lease.prepare(lease.state().plan_delta()).unwrap();
    let mut data = Vec::new();
    encode(&mut data, lease.state(), &prepared, false).unwrap();
    assert!(
        decode(
            &mut data.as_slice(),
            data.len(),
            lease.state().owned_bytes(),
            ACCOUNT
        )
        .is_ok()
    );
    let mut pending = [0u8; 11];
    pending[6..10].copy_from_slice(&499u32.to_be_bytes());
    let offset = data
        .windows(pending.len())
        .position(|bytes| bytes == pending)
        .unwrap();
    data[offset + 6..offset + 10].copy_from_slice(&500u32.to_be_bytes());
    resign(&mut data);
    assert!(
        decode(
            &mut data.as_slice(),
            data.len(),
            lease.state().owned_bytes(),
            ACCOUNT
        )
        .is_err()
    );

    while let Some(Work::Verify(candidate)) = lease.state().next_work() {
        lease
            .update(|state, limit| state.apply_facts(candidate, verified(), limit))
            .unwrap();
    }
    let prepared = lease.prepare(lease.state().plan_delta()).unwrap();
    data.clear();
    encode(&mut data, lease.state(), &prepared, false).unwrap();
    assert!(
        decode(
            &mut data.as_slice(),
            data.len(),
            lease.state().owned_bytes(),
            ACCOUNT
        )
        .is_ok()
    );
    let last_location = data.len() - CHECKSUM_BYTES - 1 - 10;
    assert_eq!(
        &data[last_location + 1..last_location + 5],
        &499u32.to_be_bytes()
    );
    data[last_location + 1..last_location + 5].copy_from_slice(&500u32.to_be_bytes());
    resign(&mut data);
    assert!(
        decode(
            &mut data.as_slice(),
            data.len(),
            lease.state().owned_bytes(),
            ACCOUNT
        )
        .is_err()
    );
}
